prompt --application/shared_components/automations/unsend_sms
begin
wwv_flow_imp_shared.create_automation(
 p_id=>wwv_flow_imp.id(54015288381421738)
,p_name=>'Unsend SMS'
,p_static_id=>'unsend-sms'
,p_trigger_type=>'POLLING'
,p_polling_interval=>'FREQ=HOURLY;INTERVAL=1;BYMINUTE=0'
,p_polling_status=>'DISABLED'
,p_result_type=>'ROWS'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_query_type=>'SQL'
,p_query_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ID, PHONE_NUMBER, MESSAGE',
'  FROM SMS_LOGS',
' WHERE IS_SEND = 0',
'   AND RESEND_COUNT <= 5',
' ORDER BY ID'))
,p_include_rowid_column=>false
,p_commit_each_row=>false
,p_error_handling_type=>'IGNORE'
);
wwv_flow_imp_shared.create_automation_action(
 p_id=>wwv_flow_imp.id(54015622945421751)
,p_automation_id=>wwv_flow_imp.id(54015288381421738)
,p_name=>'Resend SMS'
,p_execution_sequence=>10
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    buyer_object                json_object_t;',
'    v_result                    CLOB;',
'    v_message                   VARCHAR2(2000);',
'',
'BEGIN ',
'        buyer_object  := json_object_t();',
'        buyer_object.put(''to'',  TRIM(:PHONE_NUMBER));',
'        buyer_object.put(''msg'', :MESSAGE);',
'',
'        v_result := SYSTEM_INTEGRATION.sned_SMS (',
'            p_body      => buyer_object.to_clob(),',
'            p_message   => v_message',
'        );',
'        ',
'        buyer_object  := json_object_t();',
'',
'        IF v_result <> ''1'' THEN',
'            UPDATE SMS_LOGS',
'               SET IS_SEND =  0,',
'                   RESEND_COUNT = RESEND_COUNT + 1',
'            WHERE ID = :ID;',
'        ELSE',
'            UPDATE SMS_LOGS',
'               SET IS_SEND =  1,',
'                   RESEND_COUNT = RESEND_COUNT + 1',
'            WHERE ID = :ID;',
'        END IF;',
'END;'))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_error_message=>'#SQLERRM# - To: :PHONE_NUMBER, Text: :MESSAGE'
,p_stop_execution_on_error=>true
);
end;
