wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(78203901713067852)
,p_plug_name=>unistr('\0627\0644\0637\0627\0644\0628\0627\062A \0627\0644\0645\0642\062F\0645\0629')
,p_parent_plug_id=>wwv_flow_imp.id(77943820736880369)
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(146528319000969406)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH notifications AS (',
'    SELECT request_id, count(1) AS notification_count',
'      FROM individual_portable_chat',
'     WHERE is_seen = 0',
'     GROUP BY request_id',
')',
'',
'SELECT p.ID,',
'       p.MAIN_IMAGE_URL AS MAIN_IMAGE,',
'       p.NAME_AR,',
'       c.CHASSIS_NUMBER,',
'       c.PLATE_NUMBER,',
'       c.SERIAL_NUMBER,',
'       LOOKUPS_MNT.lookup_detail_name_by_id (i.REQUESTER_AS, ''ar'') AS REQUESTER_AS,',
'       i.BUYER_NAME,',
'       i.BUYER_PHONE,',
'       p.CITY_ID,',
'       p.CATEGORY_ID,',
'       p.SUB_CATEGORY_ID,',
'       i.CREATED_DATE,',
'       i.IS_PAID,',
unistr('       DECODE(PRICING_PACKAGE, ''A_99'',''\0628\0627\0642\0629 \0627\0644\0645\0631\0643\0628\0629 \0627\0644\0645\0641\062D\0648\0635\0647'',''B_149'',''\0628\0627\0642\0629 \0627\0644\0645\0631\0643\0628\0647 \0627\0644\063A\064A\0631 \0645\0641\062D\0648\0635\0647'',''C_399'',''\0627\0644\0628\0627\0642\0647 \0627\0644\0634\0627\0645\0644\0647'',''D_100'',''\0631\0633\0648\0645 \0627\0644\0625\0639\0644\0627\0646 \0639\0646 \0627\0644\0645\0632\0627\062F'',''F'','''') AS PRICING_PACKAGE,'),
'       DECODE(i.PRICING_PACKAGE, ''A_99'',''99'',''B_149'',''149'',''C_399'',''399'',''D_100'',''99'',''F'','''') AS AMOUNT,',
'       i.PROGRESS_STATUS,',
'       n.notification_count,',
'       CASE',
'        WHEN nvl(n.notification_count, 0) = 0 THEN',
'            ''<span aria-hidden="true" class="fa fa-comment-o"></span>''',
'        ELSE',
'            ''<span aria-hidden="true" class="fa fa-comment-o fa-anim-flash fam-blank fam-is-danger"></span>'' ||',
'            ''<span class="notifications-count">'' || n.notification_count || ''</span>''',
'        END AS notifications',
'  FROM PRODUCTS p,',
'       CAR_DETAILS c,',
'       INDIVIDUAL_PORTABLE_REQUESTS i,',
'       notifications n',
' WHERE p.ID = i.PRODUCT_ID',
'   AND p.ID = c.PRODUCT_ID (+)',
'   AND i.ID = n.REQUEST_ID (+)',
'   AND i.IS_ACCEPT_TERMS_AND_CONDITIONS = 1',
'   AND i.BUYER_ID NOT IN (7, 16073, 20545, 24897)',
'--    AND (i.VERSION = ''V1'' OR (i.VERSION = ''V2'' AND i.IS_PAID = 1))',
'   AND PRICING_PACKAGE IS NOT NULL',
'   AND LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => i.PROGRESS_STATUS) = ''submit_request''',
' ORDER BY n.notification_count, i.created_date DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
