'       i.CREATED_DATE,',
'       i.MODIFIED_BY,',
unistr('       DECODE(i.PRICING_PACKAGE, ''A_99'',''\0628\0627\0642\0629 \0627\0644\0645\0631\0643\0628\0629 \0627\0644\0645\0641\062D\0648\0635\0647'',''B_149'',''\0628\0627\0642\0629 \0627\0644\0645\0631\0643\0628\0647 \0627\0644\063A\064A\0631 \0645\0641\062D\0648\0635\0647'',''C_399'',''\0627\0644\0628\0627\0642\0647 \0627\0644\0634\0627\0645\0644\0647'',''D_100'',''\0631\0633\0648\0645 \0627\0644\0625\0639\0644\0627\0646 \0639\0646 \0627\0644\0645\0632\0627\062F'',''F'','''') AS PRICING_PACKAGE,'),
