'}'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_read_only_when_type=>'NOT_EXISTS'
,p_read_only_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT 1',
'  FROM INDIVIDUAL_PORTABLE_REQUESTS',
' WHERE ID = :P2_REQUEST_ID',
'   AND IS_PAID = 1',
'   AND :P_EMP_ID IN (4,17, 10, 3)',
'--    AND LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => PROGRESS_STATUS) IN (''request_approval'', ''submit_request'');',
'  AND  (',
'      PROGRESS_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''request_approval'', p_lookup_code => ''individual_auction_progress'') OR',
'      PROGRESS_STATUS  = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''submit_request'', p_lookup_code => ''individual_auction_progress'')',
'    )'))
,p_page_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_progress NUMBER;',
'BEGIN',
'    SELECT PROGRESS_STATUS',
'      INTO v_progress',
'      FROM individual_portable_requests',
'     WHERE PRODUCT_ID = :P2_ID;',
'',
'    IF :EMP_ID <> 4 ',
'    -- OR ( :EMP_ID = 4 AND LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => v_progress) NOT IN (''request_submitted'', ''submit_request'') )',
'      THEN',
'        RETURN false;',
'    ELSE',
'        RETURN true;',
'    END IF;',
'END;',
'BEGIN ',
'     IF ',
'        THEN',
'        RETURN TRUE;',
'    ELSE',
'        RETURN FALSE;',
'    END;',
'-- SELECT 1',
'--   FROM INDIVIDUAL_PORTABLE_REQUESTS',
'--  WHERE ID = :P2_REQUEST_ID',
'--    AND :EMP_ID IN (4,17, 10)',
'-- --    AND LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => PROGRESS_STATUS) IN (''request_approval'', ''submit_request'');',
'--   AND  (PROGRESS_STATUS <> LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''request_approval'', p_lookup_code => ''individual_auction_progress'')',
'--    OR  PROGRESS_STATUS <> LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''submit_request'', p_lookup_code => ''individual_auction_progress'') )',
'END;'))
,p_page_component_map=>'25'
);
