'       p.NAME_AR,',
'       p.MAIN_IMAGE_URL,',
'       p.MAP_URL,',
'       p.DESCRIPTION_AR as EXTRA_NOTES,',
'       c.VEHICLE_MAKE_ID,',
'       c.VEHICLE_MODEL_ID,',
'       c.VEHICLE_INNER_COLOR_ID,',
'       c.VEHICLE_EXTERNAL_COLOR_ID,',
'       c.TRANSMISSION_ID,',
'       c.FUEL_TYPE_ID,',
'       c.ODO_METER,',
'       c.IS_THERE_DOCUMENT,',
'       c.IS_THERE_INSPECTION,',
'       c.YEAR,',
'       c.CHASSIS_NUMBER,',
'       c.IS_DROWNED,',
'       c.IS_BURNED,',
'       c.IS_ACCIDENT,',
'       c.VEHICHLE_CATEGORY,',
'       c.PLATE_NUMBER,',
'       c.SERIAL_NUMBER,',
'       c.DROWING_INFO,',
'       c.BURN_INFO,',
'       c.ACCIDENT_INFO,',
'       c.PREVIEW_TIMES,',
'       c.PREVIEW_ADDRESS,',
'       c.PREVIEW_MAP_URL,',
'       c.PLATE_TYPE,',
'       i.ID AS REQUEST_ID,',
'       i.BUYER_ID,',
'       i.REQUESTER_AS,',
unistr('       DECODE(i.BUYER_TYPE, ''INDIVIDUAL'', ''\062D\0633\0627\0628 \0641\0631\062F'', ''\062D\0633\0627\0628 \0634\0631\0643\0629'') AS BUYER_TYPE,'),
'       i.BUYER_NAME,',
'       i.BUYER_PHONE,',
'       i.BUYER_NATIONAL_ID,',
'       i.MINIMUM_SELL_PRICE,',
'    --    i.EXTRA_NOTES,',
'       i.AUTHORIZATION_NUMBER,',
'       i.AUTHORIZATION_DATE,',
'       i.AUTHORIZATION_ADDRESS,',
