'       CASE',
'      WHEN c.INSPECTION_URL IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS INSPECTION_CLASS,',
'      c.DROWING_FILE_URL,',
'       CASE',
'      WHEN c.DROWING_FILE_URL IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS DROWING_FILE_CLASS,',
'      c.BURN_FILE_URL,',
'       CASE',
'      WHEN c.BURN_FILE_URL IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS BURN_FILE_CLASS,',
'      c.ACCIDENT_FILE_URL,',
'       CASE',
'      WHEN c.ACCIDENT_FILE_URL IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS ACCIDENT_FILE_CLASS,',
'      i.CHECKED_PACKAGE_DOC_URL,',
'       CASE',
'      WHEN i.CHECKED_PACKAGE_DOC_URL IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS CHECKED_PACKAGE_DOC_URL_CLASS,',
'      i.AUTHORIZATION_URL,',
'       CASE',
'      WHEN i.AUTHORIZATION_URL IS NOT NULL THEN',
'          ''<span class="fa fa-file-o" aria-hidden="true"></span>''',
'      ELSE ''''',
'      END AS AUTHORIZATION_URL_CLASS',
'  FROM CAR_DETAILS c,',
'       INDIVIDUAL_PORTABLE_REQUESTS i',
' WHERE i.PRODUCT_ID = :P2_ID',
'   AND c.PRODUCT_ID (+) = i.PRODUCT_ID '))
