,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
' if($v(''P2_PROGRESS_STATUS'') == $v(''P2_SUBMIT_REQUEST_LOOKUP'')) {',
'    activeStep("L36927393501154959")',
'',
'} else if ($v(''P2_PROGRESS_STATUS'') == $v(''P2_REQUEST_APPROVAL_LOOKUP'')) {',
'    activeStep("L36927393501154959")',
'    activeStep("L36927842025154960")',
'    ',
'} else if ($v(''P2_PROGRESS_STATUS'') == $v(''P2_FINAL_REQUEST_APPROVAL_LOOKUP'')) {',
'    activeStep("L36927393501154959")',
'    activeStep("L36927842025154960")',
'    activeStep("L40634246242631608")',
'',
'}else if ($v(''P2_PROGRESS_STATUS'') == $v(''P2_PUBLISH_AUCTION_LOOKUP'')) {',
'    activeStep("L36927393501154959")',
'    activeStep("L36927842025154960")',
'    activeStep("L40634246242631608")',
'    activeStep("L36928186766154960")',
'    ',
'} else if ($v(''P2_PROGRESS_STATUS'') == $v(''P2_AFTER_AUCTION_PERCEDURES_LOOKUP'')) {',
'    activeStep("L36927393501154959")',
'    activeStep("L36927842025154960")',
'    activeStep("L40634246242631608")',
'    activeStep("L36928186766154960")',
'    activeStep("L34116556525967103")',
'}',
'',
'function activeStep(elementId) {',
'  const element = document.getElementById(elementId)',
'  element.classList.add("is-active","is-complete");',
'}',
'',
'// L40634246242631608',
'// /*',
'// -- checks the status from table',
'// -- then based on the status it checked t-WizardSteps-step is-active is-complete || or t-WizardSteps-step is-active not checked ',
'//   -- 1st : L49971100659764890',
'//   --2nd: L36927842025154960',
'//   --3rd: L49971971545764892',
'//   --4th: L49972302865764892',
'// */'))
);
