'BEGIN',
'    IF :P2_SUGGESTED_PRICE IS NULL OR :P2_REASON IS NULL THEN',
unistr('        RAISE_APPLICATION_ERROR(-20011, ''\064A\062C\0628 \0639\0644\064A\0643 \062A\0639\0628\0626\0629 \0627\0644\0633\0639\0631 \0627\0644\0645\0641\062A\0631\062D \0648 \0627\0644\0633\0628\0628'');'),
'    END IF;',
'    INSERT INTO INDIVIDUAL_PORTABLE_PRICE_HISTORY ( REQUEST_ID,OLD_PRICE, SUGGESTED_PRICE, SUGGEST_REASON)',
'        VALUES (:P2_REQUEST_ID, :P2_MINIMUM_SELL_PRICE, :P2_SUGGESTED_PRICE, :P2_REASON);',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''Error in send price'');',
