'     UPDATE INDIVIDUAL_PORTABLE_REQUESTS',
'       SET IS_PRICE_EDITABLE = 1',
'     WHERE ID = :P2_REQUEST_ID;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
unistr('        RAISE_APPLICATION_ERROR(-20008, ''\062E\0637\0623 \0641\064A \062A\062D\062F\064A\062B \0628\064A\0627\0646\0627\062A \0627\0644\0637\0644\0628'');'),
'    END IF;',
'END;'))
,p_attribute_02=>'P2_MINIMUM_SELL_PRICE,P2_REQUEST_ID,P2_SUGGESTED_PRICE,P2_REASON'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
