wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(52513215219921231)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'update approve'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'   IF :P2_IS_PAID = 1 THEN ',
'       IF :P2_PROGRESS_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''submit_request'', p_lookup_code => ''individual_auction_progress'') THEN',
'            UPDATE INDIVIDUAL_PORTABLE_REQUESTS',
'               SET PROGRESS_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''request_approval'', p_lookup_code => ''individual_auction_progress''),',
'                   STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''request_approved'', p_lookup_code => ''individual_request_status''),',
'                   AFTER_APPROVAL_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''waiting_final_approval'', p_lookup_code => ''individual_portable_status'')',
'             WHERE ID = :P2_REQUEST_ID;',
'            ',
'            IF SQL%ROWCOUNT = 0 THEN',
unistr('                RAISE_APPLICATION_ERROR(-20002, ''\062E\0637\0623 \0641\064A \0627\0644\0642\0628\0648\0644 \0627\0644\0645\0628\062F\0626\064A'');'),
'            END IF;',
'       END IF;',
'    ELSE ',
unistr('        RAISE_APPLICATION_ERROR(-20003, ''\0644\0645 \064A\062A\0645 \062F\0641\0639 \0631\0633\0648\0645 \0627\0644\0628\0627\0642\0629 \062D\062A\0649 \0627\0644\0627\0646\060C \0644\0627 \064A\0645\0643\0646 \0642\0628\0648\0644 \0637\0644\0628 \0644\0645 \064A\062A\0645 \062F\0641\0639 \0631\0633\0648\0645\0647'');'),
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(51152065058843452)
,p_internal_uid=>35516314963415821
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(52513601549921235)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update info'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    UPDATE PRODUCTS',
'       SET CITY_ID = :P2_CITY_ID,',
'           MAP_URL = :P2_MAP_URL',
'     WHERE ID = :P2_ID;',
'    IF SQL%ROWCOUNT = 0 THEN',
unistr('        RAISE_APPLICATION_ERROR(-20005, ''\062E\0637\0623 \0641\064A \062A\062D\062F\064A\062B \0628\064A\0627\0646\0627\062A \0627\0644\0645\0646\062A\062C'');'),
'    END IF;',
'',
'    IF :P2_SUB_CATEGORY_ID = :P2_CAR_LOOKUP OR :P2_SUB_CATEGORY_ID = :P2_CAR_WITH_PLATE_LOOKUP THEN',
'        UPDATE PRODUCTS',
'           SET NAME_AR = LOOKUPS_MNT.vehicle_make_by_id (:P2_VEHICLE_MAKE_ID) || '' '' || LOOKUPS_MNT.vehicle_model_by_id (:P2_VEHICLE_MODEL_ID) || '' '' || :P2_YEAR || '' - (VIN:'' || SUBSTR(:P2_CHASSIS_NUMBER, - 6) || '')'',',
'               DESCRIPTION_AR = :P2_EXTRA_NOTES',
'         WHERE ID = :P2_ID;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
unistr('            RAISE_APPLICATION_ERROR(-20008, ''\062E\0637\0623 \0641\064A \062A\062D\062F\064A\062B \0628\064A\0627\0646\0627\062A \0627\0644\0645\0646\062A\062C'');'),
'        END IF;',
'    ELSIF :P2_SUB_CATEGORY_ID = :P2_PLATE_LOOKUP THEN',
'    ',
'        UPDATE PRODUCTS',
'           SET NAME_AR = :P2_PLATE_NUMBER',
'         WHERE ID = :P2_ID;',
'        IF SQL%ROWCOUNT = 0 THEN',
unistr('            RAISE_APPLICATION_ERROR(-20008, ''\062E\0637\0623 \0641\064A \062A\062D\062F\064A\062B \0628\064A\0627\0646\0627\062A \0627\0644\0645\0646\062A\062C'');'),
'        END IF;',
'    END IF;',
'',
'    UPDATE CAR_DETAILS',
'       SET VEHICLE_MAKE_ID           = :P2_VEHICLE_MAKE_ID,',
'           VEHICLE_MODEL_ID          = :P2_VEHICLE_MODEL_ID,',
'           VEHICLE_INNER_COLOR_ID    = :P2_VEHICLE_INNER_COLOR_ID,',
'           VEHICLE_EXTERNAL_COLOR_ID = :P2_VEHICLE_EXTERNAL_COLOR_ID,',
'           TRANSMISSION_ID           = :P2_TRANSMISSION_ID,',
'           FUEL_TYPE_ID              = :P2_FUEL_TYPE_ID,',
'           ODO_METER                 = :P2_ODO_METER,',
'           IS_THERE_DOCUMENT         = :P2_IS_THERE_DOCUMENT,',
'           IS_THERE_INSPECTION       = :P2_IS_THERE_INSPECTION,',
'           YEAR                      = :P2_YEAR,',
'           CHASSIS_NUMBER            = :P2_CHASSIS_NUMBER,',
'           IS_DROWNED                = :P2_IS_DROWNED,',
'           IS_BURNED                 = :P2_IS_BURNED,',
'           IS_ACCIDENT               = :P2_IS_ACCIDENT,',
'           VEHICHLE_CATEGORY         = :P2_VEHICHLE_CATEGORY,',
'           PLATE_NUMBER              = :P2_PLATE_NUMBER,',
'           SERIAL_NUMBER             = :P2_SERIAL_NUMBER,',
'           DROWING_INFO              = :P2_DROWING_INFO,',
'           BURN_INFO                 = :P2_BURN_INFO,',
'           ACCIDENT_INFO             = :P2_ACCIDENT_INFO,',
'           PREVIEW_TIMES             = :P2_PREVIEW_TIMES,',
'           PREVIEW_ADDRESS           = :P2_PREVIEW_ADDRESS,',
'           PREVIEW_MAP_URL           = :P2_PREVIEW_MAP_URL,',
'           PLATE_TYPE                = :P2_PLATE_TYPE',
'     WHERE PRODUCT_ID = :P2_ID;',
'    ',
'    IF SQL%ROWCOUNT = 0 THEN',
unistr('        RAISE_APPLICATION_ERROR(-20006, ''\062E\0637\0623 \0641\064A \062A\062D\062F\064A\062B \0628\064A\0627\0646\0627\062A \0627\0644\0645\0631\0643\0628\0629'');'),
'    END IF;',
'',
'    UPDATE INDIVIDUAL_PORTABLE_REQUESTS',
'       SET MINIMUM_SELL_PRICE = :P2_MINIMUM_SELL_PRICE--,',
'        --    EXTRA_NOTES        = :P2_EXTRA_NOTES',
'     WHERE PRODUCT_ID = :P2_ID;',
'    ',
'    IF SQL%ROWCOUNT = 0 THEN',
unistr('        RAISE_APPLICATION_ERROR(-20007, ''\062E\0637\0623 \0641\064A \062A\062D\062F\064A\062B \0628\064A\0627\0646\0627\062A \0627\0644\0637\0644\0628'');'),
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(52513568583921234)
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT 1',
'  FROM INDIVIDUAL_PORTABLE_REQUESTS',
' WHERE ID = :P2_REQUEST_ID',
'   AND :P_EMP_ID IN (4,17, 10, 3)',
'  AND  (PROGRESS_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''request_approval'', p_lookup_code => ''individual_auction_progress'')',
'   OR  PROGRESS_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''submit_request'', p_lookup_code => ''individual_auction_progress'') )'))
,p_process_when_type=>'EXISTS'
,p_internal_uid=>35516701293415825
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(52698142243042121)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Final approval - Send request'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_inserted                  NUMBER;',
'    v_buyer_vehicle_id          NUMBER;',
'    v_res_product_id            NUMBER;',
'    v_buyer_id                  VARCHAR2(2000);',
'    v_name                      VARCHAR2(2000);',
'    v_city_id                   VARCHAR2(2000);',
'    v_category_id               VARCHAR2(2000);',
'    v_sub_category_id           VARCHAR2(2000);',
'    v_main_image                VARCHAR2(2000);',
'    v_description               VARCHAR2(2000);',
'    v_make_id                   VARCHAR2(2000);',
'    v_model_id                  VARCHAR2(2000);',
'    v_color_id                  VARCHAR2(2000);',
'    v_fuel_type                 VARCHAR2(2000);',
'    v_odo_meter                 VARCHAR2(2000);',
'    v_is_there_document         VARCHAR2(2000);',
'    v_is_there_inspection       VARCHAR2(2000);',
'    v_year                      VARCHAR2(2000);',
'    v_chassis_number            VARCHAR2(2000);',
'    v_is_drowned                VARCHAR2(2000);',
'    v_is_burned                 VARCHAR2(2000);',
'    v_is_accident               VARCHAR2(2000);',
'    v_vehichle_category         VARCHAR2(2000);',
'    v_plate_number              VARCHAR2(2000);',
'    v_serial_number             VARCHAR2(2000);',
'    v_drowing_info              VARCHAR2(2000);',
'    v_drowing_file_url          VARCHAR2(2000);',
'    v_burn_info                 VARCHAR2(2000);',
'    v_burn_file_url             VARCHAR2(2000);',
'    v_accident_info             VARCHAR2(2000);',
'    v_accident_file_url         VARCHAR2(2000);',
'    v_preview_times             VARCHAR2(2000);',
'    v_preview_address           VARCHAR2(2000);',
'    v_preview_map_url           VARCHAR2(2000);',
'    v_minimum_acceptable_price  VARCHAR2(2000);',
'    v_authorization_number      VARCHAR2(2000);',
'    v_authorization_date        VARCHAR2(2000);',
'    v_authorization_address     VARCHAR2(2000);',
'    v_authorization_url         VARCHAR2(2000);',
'    v_pricing_package           VARCHAR2(2000);',
'    v_is_accept_terms           VARCHAR2(2000);',
'    v_document_url              VARCHAR2(2000);',
'    v_inspection_url            VARCHAR2(2000);',
'    v_images_urls               VARCHAR2(2000);',
'    v_checked_package_doc_url   VARCHAR2(2000);',
'    l_result                    VARCHAR2(2000);',
'    l_message                   CLOB;',
'    l_status                    VARCHAR2(2000);',
'    v_urls                      APEX_T_VARCHAR2;',
'    header                      json_object_t;',
'    car_details_object          json_object_t;',
'    buyer_object                json_object_t;',
'    reports_object              json_object_t;',
'    report_name                 json_object_t;',
'    name_object                 json_object_t;',
'    description_object          json_object_t;',
'    address_object              json_object_t;',
'    reports_array               json_array_t;',
'    images_urls_array           json_array_t;',
'    v_result                    CLOB;',
'    v_message                   VARCHAR2(2000);',
'BEGIN',
'    header                  := json_object_t();',
'    car_details_object      := json_object_t();',
'    buyer_object            := json_object_t();',
'    reports_object          := json_object_t();',
'    report_name             := json_object_t();',
'    name_object             := json_object_t();',
'    description_object      := json_object_t();',
'    address_object          := json_object_t();',
'    reports_array           := json_array_t();',
'    images_urls_array       := json_array_t();',
'',
'    IF :P2_IS_CREATED = 0 THEN',
'        SELECT i.BUYER_ID, p.NAME_AR, p.CITY_ID, p.CATEGORY_ID, p.SUB_CATEGORY_ID, p.MAIN_IMAGE_URL, p.IMAGES_URLS, p.DESCRIPTION_AR, c.VEHICLE_MAKE_ID /*LOOKUPS_MNT.vehicle_make_by_id (c.VEHICLE_MAKE_ID)*/,',
'               c.VEHICLE_MODEL_ID /*LOOKUPS_MNT.vehicle_model_by_id (c.VEHICLE_MODEL_ID)*/, c.VEHICLE_EXTERNAL_COLOR_ID /*LOOKUPS_MNT.vehicle_color_by_id (c.VEHICLE_EXTERNAL_COLOR_ID)*/,',
'               upper(LOOKUPS_MNT.lookup_detail_code_by_id (c.FUEL_TYPE_ID)), c.ODO_METER, c.IS_THERE_DOCUMENT, c.IS_THERE_INSPECTION, c.DOCUMENT_URL, c.INSPECTION_URL, c.YEAR, c.CHASSIS_NUMBER, c.IS_DROWNED,',
'               c.IS_BURNED, c.IS_ACCIDENT, upper(LOOKUPS_MNT.lookup_detail_code_by_id (c.VEHICHLE_CATEGORY)), c.PLATE_NUMBER, c.SERIAL_NUMBER, c.DROWING_INFO, c.DROWING_FILE_URL, c.BURN_INFO, c.BURN_FILE_URL,',
'               c.ACCIDENT_INFO, c.ACCIDENT_FILE_URL, c.PREVIEW_TIMES, c.PREVIEW_ADDRESS, c.PREVIEW_MAP_URL, c.MINIMUM_ACCEPTABLE_PRICE, i.AUTHORIZATION_NUMBER, to_char(i.AUTHORIZATION_DATE, ''YYYY-MM-DD''),',
'               i.AUTHORIZATION_ADDRESS, i.AUTHORIZATION_URL, i.PRICING_PACKAGE, i.IS_ACCEPT_TERMS_AND_CONDITIONS, i.CHECKED_PACKAGE_DOC_URL',
'          INTO v_buyer_id, v_name, v_city_id, v_category_id, v_sub_category_id, v_main_image, v_images_urls, v_description, v_make_id, v_model_id, v_color_id, v_fuel_type, v_odo_meter, v_is_there_document,',
'               v_is_there_inspection, v_document_url, v_inspection_url, v_year, v_chassis_number, v_is_drowned, v_is_burned, v_is_accident, v_vehichle_category, v_plate_number, v_serial_number,',
'               v_drowing_info, v_drowing_file_url, v_burn_info, v_burn_file_url, v_accident_info, v_accident_file_url, v_preview_times, v_preview_address, v_preview_map_url, v_minimum_acceptable_price,',
'               v_authorization_number, v_authorization_date, v_authorization_address, v_authorization_url, v_pricing_package, v_is_accept_terms, v_checked_package_doc_url',
'          FROM PRODUCTS p,',
'               CAR_DETAILS c,',
'               INDIVIDUAL_PORTABLE_REQUESTS i',
'         WHERE p.ID = c.PRODUCT_ID (+)',
'           AND p.ID = i.PRODUCT_ID',
'           AND p.ID = :P2_ID;',
'',
'        FOR i IN (SELECT NAME_AR , REPORT_URL',
'                    FROM PRODUCT_REPORTS',
'                   WHERE PRODUCT_ID = :P2_ID)',
'        LOOP',
'            report_name.put(''ar-SA'', i.NAME_AR);',
'',
'            reports_object.put(''id'',        ''id'');',
'            reports_object.put(''nameTrans'', report_name);',
'            reports_object.put(''reportUrl'', i.REPORT_URL);',
'',
'            reports_array.append(reports_object);',
'            report_name     := json_object_t();',
'            reports_object  := json_object_t();',
'        END LOOP;',
'',
'        name_object.put(''ar-SA'', TRIM(v_name));',
'        description_object.put(''ar-SA'', TRIM(v_description));',
'        address_object.put(''ar-SA'', TRIM(v_preview_address));',
'',
'        v_urls := APEX_STRING.split ( p_str => v_images_urls, p_sep => '','' );',
'',
'        IF v_urls.count > 1 THEN',
'            FOR k IN 1 .. v_urls.count LOOP',
'                images_urls_array.append(v_urls(k));',
'            END LOOP;',
'        ELSIF v_urls.count = 1 THEN',
'            images_urls_array.append(v_images_urls);',
'        END IF;',
'',
'        -- "city": {',
'        --     "lookupCode": "Abha" //City key',
'        -- }',
'',
'        -- CAR DETAILS object',
'        car_details_object.put(''id'',                   ''id'');',
'        -- car_details_object.put(''product'',              :P2_ID);',
'        car_details_object.put(''vehiclesmake'',         TRIM(v_make_id));',
'        car_details_object.put(''vehiclesmodel'',        v_model_id);',
'        car_details_object.put(''vehicleexternalcolor'', TRIM(v_color_id));',
'        car_details_object.put(''fuelType'',             TRIM(v_fuel_type));',
'        car_details_object.put(''odometer'',             TRIM(v_odo_meter));',
'        car_details_object.put(''isThereDocument'',      TRIM(v_is_there_document));',
'        car_details_object.put(''isThereInspection'',    TRIM(v_is_there_inspection));',
'        car_details_object.put(''year'',                 v_year);',
'        car_details_object.put(''vinNumber'',            v_chassis_number);',
'        car_details_object.put(''plateNumber'',          v_plate_number);',
'        car_details_object.put(''previewTimes'',         v_preview_times);',
'        car_details_object.put(''isThereBurning'',       v_is_burned);',
'        car_details_object.put(''isThereSinking'',       v_is_drowned);',
'        car_details_object.put(''accidentsNotes'',       v_accident_info);',
'        car_details_object.put(''isThereAccidents'',     v_is_accident);',
'        car_details_object.put(''burningNotes'',         v_burn_info);',
'        car_details_object.put(''sinkingNotes'',         v_drowing_info);',
'        car_details_object.put(''serialNo'',             v_serial_number);',
'        car_details_object.put(''previewLocation'',      v_preview_address);',
'        car_details_object.put(''vehiclesclass'',        v_vehichle_category);',
'        car_details_object.put(''inspectionUrl'',        v_inspection_url);',
'        car_details_object.put(''documentUrl'',          v_document_url);',
'        car_details_object.put(''accidentsUrls'',         v_accident_file_url);',
'        car_details_object.put(''burningUrls'',           v_burn_file_url);',
'        car_details_object.put(''sinkingUrls'',           v_drowing_file_url);',
'',
'        -- BUYER Vechile object',
'        buyer_object.put(''id'',                      ''id'');',
'        buyer_object.put(''buyer'',                   TRIM(v_buyer_id));',
'        buyer_object.put(''authorizationNumber'',     TRIM(v_authorization_number));',
