wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(52700174475042141)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update assigned details'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_inserted NUMBER;',
'BEGIN',
'    FOR j IN (SELECT jt.success, jt.productId, jt.message',
'                FROM JSON_TABLE (:P2_RESPONSE,',
'                 ''$.results[*]''',
'                  COLUMNS (',
'                      success     varchar2(500) path ''$.success'',',
'                      productId   varchar2(500) path ''$.productId'',',
'                      sellerId    varchar2(500) path ''$.sellerId'',',
'                      message     varchar2(500) path ''$.message'',',
'                      vinNumber   varchar2(500) path ''$.vinNumber''',
'                    )',
'                ) AS jt',
'                 WHERE :P2_CHASSIS_NUMBER = jt.vinNumber)',
'    LOOP',
'        IF j.success = ''true'' THEN',
'            v_inserted := 1;',
'        ELSE',
'            v_inserted := 0;',
'        END IF;',
'        UPDATE SELLER_ASSIGNED_FILES_DETAILS',
'           SET RES_PRODUCT_ID = j.productId,',
'               RES_MESSAGE  = j.message,',
'               IS_INSERTED  = v_inserted',
'         WHERE ID = :P2_ASSIGNED_ID;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20005, ''Updating Error  '');',
'        END IF;',
'    END LOOP;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(52698001855042120)
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P2_PRICING_PACKAGE = ''C_400'' AND LOOKUPS_MNT.lookup_detail_code_by_id (p_lookup_detail_id => :P2_PROGRESS_STATUS)',
'                                                     IN (''request_submitted'', ''submit_request'') THEN',
'        RETURN TRUE;',
'    ELSE',
'        RETURN FALSE;',
'    END IF;',
'END;'))
,p_process_when_type=>'FUNCTION_BODY'
,p_process_when2=>'PLSQL'
,p_internal_uid=>35703274218536731
);
