'    l_result := SYSTEM_INTEGRATION.individual_realestate_seller_assign (',
'                        p_body     => header.to_clob(),',
'                        p_id       => :P36_AUCTION_ID,',
'                        p_message  => l_message',
'                    );',
'',
'    header  := json_object_t();',
'',
'    IF l_result <> ''1'' THEN',
'        RAISE_APPLICATION_ERROR(-20003, l_message);',
'    END IF;',
'END;'))
,p_attribute_02=>'P3_SELLER_ASSIGN'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_server_condition_type=>'NEVER'
);
