 p_id=>wwv_flow_imp.id(55086149331576912)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update the message to be seen'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_count NUMBER;',
'BEGIN',
'    SELECT COUNT(1)',
'      INTO v_count',
'      FROM individual_portable_chat',
'     WHERE request_id = :P3_ID',
'       AND is_seen = 0;',
'',
'    IF v_count <> 0 THEN',
'        UPDATE individual_portable_chat',
'           SET is_seen = 1',
'         WHERE request_id = :P3_ID;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
unistr('            RAISE_APPLICATION_ERROR(-20003, ''\062E\0637\0623 \0641\064A \062D\0627\0644\0629 \0631\0624\064A\0629 \0627\0644\0631\0633\0627\0626\0644 \0627\0644\062C\062F\064A\062F\0629'');'),
'        END IF;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>38089249075071502
);
