'    UPDATE INDIVIDUAL_PORTABLE_REQUESTS',
'       SET PROGRESS_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''decline_auction'', p_lookup_code => ''individual_auction_progress''),',
'           REJECT_REASON = :P4_REASON,',
'           REQUEST_STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''decline'', p_lookup_code => ''individuals_auctions_status''),',
'           STATUS = LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''declined_request'', p_lookup_code => ''individual_request_status'')',
'     WHERE ID = :P4_ID;',
'     ',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR (-20007, ''Updating Error!'');',
'    END IF;',
'',
'    -- sms_object.put(''to'',  ''+9660'' || TRIM(:P4_BUYER_PHONE));',
unistr('    -- sms_object.put(''msg'', ''\0625\0634\0639\0627\0631 \0628\062A\062D\062F\064A\062B \062D\0627\0644\0629 \0627\0644\0637\0644\0628 \0628\0631\0641\0636 \0637\0644\0628\0643\060C \0644\0645\0639\0631\0641\0629 \0627\0644\0645\0632\064A\062F \0627\0644\0631\062C\0627\0621 \0632\064A\0627\0631\0629 \0645\0648\0642\0639 \0645\0628\0627\0634\0631'');'),
