wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(53112152061553528)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create product Locally - agets requests'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_res_product_id             NUMBER;',
'    v_seller_id                  NUMBER;',
'    v_check_seller               NUMBER;',
'    v_detail_seq                 NUMBER;',
'    v_seq                        NUMBER;',
'    v_master_id                  NUMBER;',
'    v_inserted                   NUMBER;',
'    v_city_id                    VARCHAR2(2550);',
'    v_category_id                VARCHAR2(2550);',
'    v_sub_category_id            VARCHAR2(2550);',
'    v_name_ar                    VARCHAR2(2550);',
'    v_main_image_url             VARCHAR2(2550);',
'    v_images_urls                VARCHAR2(2550);',
'    v_vehicle_make_id            VARCHAR2(2550);',
'    v_vehicle_model_id           VARCHAR2(2550);',
'    v_vehicle_external_color_id  VARCHAR2(2550);',
'    v_fuel_type_id               VARCHAR2(2550);',
'    v_odo_meter                  VARCHAR2(2550);',
'    v_year                       VARCHAR2(2550);',
'    v_chassis_number             VARCHAR2(2550);',
'    v_is_drowned                 VARCHAR2(2550);',
'    v_is_burned                  VARCHAR2(2550);',
'    v_is_accident                VARCHAR2(2550);',
'    v_vehichle_category          VARCHAR2(2550);',
'    v_plate_number               VARCHAR2(2550);',
'    v_serial_number              VARCHAR2(2550);',
'    v_is_there_document          VARCHAR2(2550);',
'    v_is_there_inspection        VARCHAR2(2550);',
'    v_accident_info              VARCHAR2(2550);',
'    v_preview_times              VARCHAR2(2550);',
'    v_preview_address            VARCHAR2(2550);',
'    v_preview_map_url            VARCHAR2(2550);',
'BEGIN',
'    SELECT MAX(SEQUENCE) + 1 INTO v_seq FROM SELLER_ASSIGNED_FILES_MASTER;',
'    SELECT ID INTO v_seller_id FROM SELLERS WHERE IDENTITY_NUMBER = 1010734256;',
'',
'    SELECT COUNT(1)',
'      INTO v_check_seller',
'      FROM SELLER_ASSIGNED_FILES_MASTER',
'     WHERE SELLER_ID = v_seller_id',
'       AND USER_ID = :P5_ASSIGNED_PHOTO_AGENT',
'       AND CHECKER_USER_ID = :P5_ASSIGNED_INSPECTION_AGENT',
'       AND TYPE = ''INDIVIDUALS'';',
'',
'    IF v_check_seller = 0 THEN',
'        INSERT INTO SELLER_ASSIGNED_FILES_MASTER ( SELLER_ID, USER_ID, CHECKER_USER_ID, SEQUENCE, NAME, IS_ACTIVE, STATUS_ID, TYPE )',
'            VALUES (v_seller_id, :P5_ASSIGNED_PHOTO_AGENT, :P5_ASSIGNED_INSPECTION_AGENT, v_seq, SELLER.seller_name(p_seller_id => v_seller_id), 1,',
'                    LOOKUPS_MNT.lookup_detail_id_by_code (p_lookup_detail_code => ''done'', p_lookup_code => ''seller_assigned_files_status''), ''INDIVIDUALS'' )',
'        RETURNING ID INTO v_master_id;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            RAISE_APPLICATION_ERROR(-20003, ''EEROR IN MASTER'');',
'        END IF;',
'    ELSE',
'        SELECT ID',
'          INTO v_master_id',
'          FROM SELLER_ASSIGNED_FILES_MASTER',
'         WHERE SELLER_ID = v_seller_id',
'           AND USER_ID = :P5_ASSIGNED_PHOTO_AGENT',
'           AND CHECKER_USER_ID = :P5_ASSIGNED_INSPECTION_AGENT',
'           AND TYPE = ''INDIVIDUALS'';',
'    END IF;',
'',
'    SELECT LOOKUPS_MNT.lookup_detail_name_by_id ( p_lookup_detail_id => p.CITY_ID , p_lang => ''ar'') AS CITY_ID,',
'           LOOKUPS_MNT.lookup_detail_name_by_id ( p_lookup_detail_id => p.CATEGORY_ID, p_lang => ''ar'') AS CATEGORY_ID,',
'           LOOKUPS_MNT.lookup_detail_name_by_id ( p_lookup_detail_id => p.SUB_CATEGORY_ID, p_lang => ''ar'') AS SUB_CATEGORY_ID,',
'           (SELECT NAME_AR FROM VEHICLE_MAKE  WHERE  ID = c.VEHICLE_MAKE_ID) AS VEHICLE_MAKE_ID,',
'           (SELECT NAME_AR FROM VEHICLE_MODEL WHERE ID = c.VEHICLE_MODEL_ID) AS VEHICLE_MODEL_ID,',
'           (SELECT NAME_AR FROM VEHICLE_EXTERNAL_COLOR WHERE ID = c.VEHICLE_EXTERNAL_COLOR_ID) AS VEHICLE_EXTERNAL_COLOR_ID,',
'           c.CHASSIS_NUMBER, c.PLATE_NUMBER, c.ODO_METER, c.YEAR, c.SERIAL_NUMBER,',
'           LOOKUPS_MNT.lookup_detail_name_by_id ( p_lookup_detail_id => c.FUEL_TYPE_ID, p_lang => ''ar'') AS FUEL_TYPE_ID,',
'           DECODE(c.IS_DROWNED, 1, ''True'',0, ''False'' ) AS IS_DROWNED,',
'           DECODE(c.IS_BURNED, 1, ''True'',0, ''False'' ) AS  IS_BURNED,',
'           DECODE(c.IS_ACCIDENT, 1, ''True'',0, ''False'' ) AS IS_ACCIDENT,',
unistr('           DECODE(c.IS_THERE_DOCUMENT, 1, ''\0645\062C\062F\062F\0629 (\0633\0627\0631\064A\0629)'','),
unistr('            0, ''\0645\0646\062A\0647\064A\0629 (\063A\064A\0631 \0633\0627\0631\064A\0629)'' ) AS IS_THERE_DOCUMENT,'),
unistr('           DECODE(c.IS_THERE_INSPECTION, 1, ''\0633\0627\0631\064A'','),
unistr('           0, ''\0644\0627\064A\0648\062C\062F \0641\062D\0635'' ) AS IS_THERE_INSPECTION,'),
'           c.PREVIEW_TIMES, c.PREVIEW_ADDRESS, c.PREVIEW_MAP_URL, c.VEHICHLE_CATEGORY, p.IMAGES_URLS, p.MAIN_IMAGE_URL',
'      INTO v_city_id, v_category_id, v_sub_category_id, v_vehicle_make_id, v_vehicle_model_id, v_vehicle_external_color_id,',
'           v_chassis_number, v_plate_number, v_odo_meter, v_year, v_serial_number, v_fuel_type_id, v_is_drowned,',
'           v_is_burned, v_is_accident, v_is_there_document, v_is_there_inspection, v_preview_times, v_preview_address,',
'           v_preview_map_url, v_vehichle_category, v_main_image_url, v_images_urls',
'      FROM PRODUCTS p,',
'           CAR_DETAILS c',
'     WHERE p.ID = :P5_PRODUCT_ID',
'       AND p.ID = c.PRODUCT_ID;',
'',
'    SELECT MAX(SEQUENCE) + 1 INTO v_detail_seq FROM SELLER_ASSIGNED_FILES_DETAILS;',
'    SELECT RES_PRODUCT_ID INTO v_res_product_id FROM INDIVIDUAL_PORTABLE_REQUESTS WHERE PRODUCT_ID = :P5_PRODUCT_ID;',
'',
'    INSERT INTO SELLER_ASSIGNED_FILES_DETAILS (',
'                MASTER_ID, RES_PRODUCT_ID, SELLER_ID,USER_ID,CHECKER_USER_ID,SEQUENCE,PRODUCT_DEPENDENCY,CITY,CATEGORY,SUB_CATEGORY,MAKE,',
'                MODEL, CLASS,CHASSIS_NUMBER,PLATE_NUMBER,COLOR,WALKWAY,YEAR,FUEL_TYPE,SERIAL_NUMBER,IS_DRAWED,IS_BURNED,',
'                IS_ACCIDENT,ISTEMARA_EXPIRATION,PERIODIC_INSPECTION,PREVIEW_TIMES,ADDRESS,MAP_URL,IMAGES_URLS,MAIN_IMAGE_URL',
'        ) VALUES ( ',
'                v_master_id, v_res_product_id,v_seller_id,:P5_ASSIGNED_PHOTO_AGENT,:P5_ASSIGNED_INSPECTION_AGENT, v_detail_seq,''INDIVIDUAL_PRODUCT'',',
'                v_city_id,v_category_id,v_sub_category_id,v_vehicle_make_id,v_vehicle_model_id,v_vehichle_category,',
'                trim(v_chassis_number),v_plate_number,v_vehicle_external_color_id, v_odo_meter,v_year,v_fuel_type_id,v_serial_number,',
'                v_is_drowned,v_is_burned,v_is_accident,v_is_there_document,v_is_there_inspection,v_preview_times,v_preview_address,',
'                v_preview_map_url,v_images_urls,v_main_image_url',
'        ) RETURNING ID INTO :P5_ASSIGNED_ID;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20005, ''Insertion Error'');',
'    END IF;',
'',
'    UPDATE INDIVIDUAL_PORTABLE_REQUESTS',
'       SET is_agent_assigned = 1',
'     WHERE id = :P5_REQUEST_ID;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20007, ''Update Request Error'');',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(52699393571042133)
,p_process_success_message=>unistr('\062A\0645 \0625\0631\0633\0627\0644 \0627\0644\0637\0644\0628 \0628\0646\062C\0627\062D')
,p_internal_uid=>36115251805048118
);
