,p_region_template_options=>'#DEFAULT#:t-IRR-region--noBorders'
,p_plug_template=>wwv_flow_imp.id(146528319000969406)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_result clob;',
'    l_single_image clob;',
'    l_single_elemant APEX_T_VARCHAR2;',
'    items VARCHAR2(5000);',
'    items_array  APEX_T_VARCHAR2;',
'    total integer;',
'    v_seq NUMBER := 1;',
'BEGIN',
'    SELECT IMAGES_URLS',
'      into items',
'      FROM  PRODUCTS',
'     WHERE ID = :P7_ID;',
'',
'    IF items IS NOT NULL THEN',
'    :P7_URLS := items ;',
'    l_result := l_result ||''<div class="images">'';',
'',
'        l_single_elemant := apex_string.SPLIT (',
'                            p_str => items,',
'                            p_sep => '','' );',
'  ',
'     FOR i in 1 ..l_single_elemant.COUNT LOOP',
'        l_single_image := ''<div class = "single-image" id= "'' || v_seq ||''" data-id = "'' || v_seq || ''"><span aria-hidden="true" class="fa fa-remove fa-lg"></span>',
'                           <img src="''|| l_single_elemant(i) ||''" alt=""> </div> '';',
'        l_result := l_result || l_single_image;',
'        -- l_result := l_result || ''<img src="''|| l_single_elemant(i) ||''" alt="">'';',
'        v_seq := v_seq + 1;',
'    END LOOP;                     ',
'    l_result := l_result ||   ''</div>'';',
'    END IF;',
'',
'    RETURN l_result;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P7_ID'
);
