wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(29819408806678057)
,p_event_id=>wwv_flow_imp.id(29818917059678056)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_affected_elements_type=>'ITEM'
,p_affected_elements=>'P7_SRC,P7_URLS'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function getImageSrc(){',
'    let singleImgId = $v(''P7_DELETE_IMAGE''),',
'        urls = $v(''P7_URLS''),',
'        urlsArray = [],',
'        imgSrc',
'',
'    if ( singleImgId && document.getElementById(singleImgId)){',
'        let imageElement = document.getElementById(singleImgId).querySelector(''img'');',
'        if (imageElement) {',
'            imgSrc = imageElement.src;',
'            $s(''P7_SRC'', imgSrc);',
'            // console.log(''src: '', imgSrc);',
'            // console.log('' prev urls: '', urls );',
'        }',
'    }                           else {',
'        console.log(''no id'');',
'    }',
'    const result = urls.split(/[,]+/);',
'        // console.log(result);',
'    // newUrls = urls.filter(function(e) {return e != imgSrc});',
'    // urls.filter(function(e) {return e != imgSrc});',
'    //  result.filter(e => {return e != imgSrc});',
'    urlsArray = result.filter((url) => url != imgSrc);',
'    $s(''P7_URLS'', urlsArray);',
'    // console.log(''new urls : '',  urlsArray);',
'}',
'getImageSrc();'))
);
