wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(29821919147678058)
,p_event_id=>wwv_flow_imp.id(29818917059678056)
,p_event_result=>'TRUE'
,p_action_sequence=>50
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_original_urls VARCHAR(4000);',
'BEGIN',
'    SELECT IMAGES_URLS',
'      INTO l_original_urls',
'      FROM PRODUCTS',
'     WHERE ID = :P7_ID;',
'',
'    INSERT INTO URLS_HISTORY (ORIGINAL_URL, UPDATED_URL, OBJECT_ID, TYPE, URL_TYPE)',
'      VALUES (l_original_urls, :P7_URLS, :P7_ID, ''PRODUCTS'', ''IMAGES_URLS'');',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
unistr('        RAISE_APPLICATION_ERROR(-20017, ''\062E\0637\0623 \062D\0630\0641 \0627\0644\0635\0648\0631\0629!'');'),
'    END IF;',
'',
'    UPDATE PRODUCTS',
'       SET IMAGES_URLS = :P7_URLS',
'     WHERE ID = :P7_ID;',
'    ',
'    IF SQL%ROWCOUNT = 0 THEN',
unistr('        RAISE_APPLICATION_ERROR(-20019, ''\062E\0637\0623 \062D\0630\0641 \0627\0644\0645\0631\0641\0642!'');'),
'    END IF;',
'END;'))
,p_attribute_02=>'P7_ID,P7_URLS'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
