wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(29816410498678053)
,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload product images'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_name         VARCHAR2(255);',
'    l_request_url	    VARCHAR2(32767);',
'    l_result	        CLOB;',
'    items VARCHAR2(5000);',
'BEGIN',
'    FOR i IN (SELECT c001 AS FILE_NAME, c002 AS MIME_TYPE, blob001 AS BLOB_CONTENT FROM apex_collections WHERE collection_name = ''DROPZONE_UPLOAD'') LOOP',
'        l_file_name := TO_CHAR(get_current_date, ''YY'') ',
'                            || DBMS_RANDOM.STRING(''x'', 8)',
'                            || SYSTEM_CONTROLS.file_extension_by_mimetype(p_mimetype => i.MIME_TYPE);',
'',
'        l_request_url := :LOCATION_URI || l_file_name;',
'',
'        DBMS_CLOUD.put_object (',
'            credential_name => :CREDENTIAL_NAME,',
'            object_uri      => l_request_url,',
'            contents        => i.blob_content',
'        );',
'',
'        SELECT IMAGES_URLS',
'          into items',
'          FROM  PRODUCTS',
'         WHERE ID = :P7_ID;',
'        ',
'        if items is null then',
'            items := l_request_url;',
'        else',
'            items := items || '','' || l_request_url;',
'        end if;',
'        update PRODUCTS',
'           set IMAGES_URLS = items',
'          where id = :P7_ID;',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
unistr('            RAISE_APPLICATION_ERROR(-20016, ''\062E\0637\0623 \0641\064A \0631\0641\0639 \0627\0644\0635\0648\0631!'');'),
'        END IF;',
'    END LOOP;',
'    ',
'    SELECT IMAGES_URLS',
'      INTO items',
'      FROM  PRODUCTS',
'     WHERE ID = :P7_ID;',
'',
'    INSERT INTO URLS_HISTORY (ORIGINAL_URL, UPDATED_URL, OBJECT_ID, TYPE, URL_TYPE)',
'         VALUES (:P7_URLS, items, :P7_ID, ''PRODUCTS'', ''IMAGES_URLS'');',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
unistr('        RAISE_APPLICATION_ERROR(-20017, ''\062E\0637\0623 \0641\064A \0631\0641\0639 \0627\0644\0635\0648\0631!'');'),
'    END IF;',
'    ',
'    APEX_COLLECTION.TRUNCATE_COLLECTION (p_collection_name => ''DROPZONE_UPLOAD'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(29810321125678045)
,p_process_when=>'SELECT 1 FROM apex_collections WHERE collection_name = ''DROPZONE_UPLOAD'''
,p_process_when_type=>'EXISTS'
,p_process_success_message=>unistr('\062A\0645 \0625\0636\0627\0641\0629 \0627\0644\0635\0648\0631 \0628\0646\062C\0627\062D')
,p_internal_uid=>25000938041606659
);
